=== public/style.css ===
:root {
  --primary: #2563eb;
  --primary-dark: #1e40af;
  --bg: #f4f6fb;
  --card: #ffffff;
  --text: #1f2937;
  --muted: #6b7280;
  --border: #e5e7eb;
  --ok: #16a34a;
  --warn: #d97706;
  --bad: #dc2626;
  --pending: #d97706;
  --confirmed: #16a34a;
  --rejected: #dc2626;
  --cancelled: #6b7280;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
}

.topbar {
  background: var(--card);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 50;
}
.topbar-inner {
  max-width: 1080px;
  margin: 0 auto;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.brand { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 18px; }
.logo { font-size: 22px; }
.brand-name { color: var(--primary-dark); }

#authArea { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.user-chip { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.2; }
.user-chip .un { font-weight: 600; font-size: 14px; }
.user-chip .ur { font-size: 12px; color: var(--muted); }
.user-chip .ur.owner { color: var(--primary); }

.app { max-width: 1080px; margin: 0 auto; padding: 20px 16px 60px; }

/* Buttons */
.btn {
  border: 1px solid transparent;
  background: var(--primary);
  color: #fff;
  padding: 10px 16px;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background .15s, transform .05s;
}
.btn:hover { background: var(--primary-dark); }
.btn:active { transform: translateY(1px); }
.btn:disabled { opacity: .5; cursor: not-allowed; }
.btn.secondary { background: #fff; color: var(--text); border-color: var(--border); }
.btn.secondary:hover { background: #f9fafb; }
.btn.small { padding: 6px 10px; font-size: 13px; border-radius: 8px; }
.btn.danger { background: var(--bad); }
.btn.danger:hover { background: #b91c1c; }
.btn.ghost { background: transparent; color: var(--primary); }
.btn.ghost:hover { background: rgba(37,99,235,.08); }

/* Forms */
.field { margin-bottom: 14px; }
.field label { display: block; font-size: 13px; font-weight: 600; margin-bottom: 6px; color: var(--muted); }
.field input, .field select, .field textarea {
  width: 100%;
  padding: 11px 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  font-size: 15px;
  background: #fff;
  color: var(--text);
}
.field input:focus, .field select:focus, .field textarea:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(37,99,235,.12);
}
.field textarea { resize: vertical; min-height: 70px; }

/* Cards */
.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 18px;
  box-shadow: 0 1px 3px rgba(0,0,0,.04);
}
.card + .card { margin-top: 16px; }
.card h2 { margin: 0 0 4px; font-size: 19px; }
.card h3 { margin: 0 0 10px; font-size: 16px; }
.muted { color: var(--muted); font-size: 13px; }

/* Auth page */
.auth-wrap { max-width: 420px; margin: 40px auto; }
.tabs { display: flex; gap: 6px; margin-bottom: 16px; background: #eef1f6; padding: 5px; border-radius: 12px; }
.tab {
  flex: 1;
  text-align: center;
  padding: 10px;
  border-radius: 9px;
  cursor: pointer;
  font-weight: 600;
  font-size: 14px;
  color: var(--muted);
}
.tab.active { background: #fff; color: var(--primary); box-shadow: 0 1px 2px rgba(0,0,0,.08); }

/* Tabs (app) */
.tabbar { display: flex; gap: 6px; margin-bottom: 16px; flex-wrap: wrap; }
.tabbar .tab { flex: 0 0 auto; }

/* Services grid */
.grid { display: grid; gap: 14px; grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); }
.service-card { cursor: pointer; transition: border-color .15s, transform .05s; }
.service-card:hover { border-color: var(--primary); }
.service-card.selected { border-color: var(--primary); box-shadow: 0 0 0 2px rgba(37,99,235,.18); }
.service-name { font-size: 16px; font-weight: 700; margin-bottom: 4px; }
.service-desc { font-size: 13px; color: var(--muted); margin-bottom: 10px; min-height: 18px; }
.service-meta { display: flex; justify-content: space-between; align-items: center; }
.price { font-weight: 700; color: var(--primary-dark); font-size: 15px; }
.duration { font-size: 12px; color: var(--muted); }

/* Availability */
.avail-wrap { margin-top: 16px; }
.avail-days { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 8px; }
.day-chip {
  flex: 0 0 auto;
  text-align: center;
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 10px;
  cursor: pointer;
  min-width: 62px;
  background: #fff;
}
.day-chip .dw { font-size: 12px; color: var(--muted); }
.day-chip .dd { font-size: 16px; font-weight: 700; }
.day-chip.active { background: var(--primary); border-color: var(--primary); }
.day-chip.active .dw, .day-chip.active .dd { color: #fff; }
.day-chip.nofree { opacity: .4; }

.slots { display: grid; gap: 8px; grid-template-columns: repeat(auto-fill, minmax(90px, 1fr)); margin-top: 12px; }
.slot {
  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 9px;
  text-align: center;
  cursor: pointer;
  font-weight: 600;
  background: #fff;
}
.slot:hover { border-color: var(--primary); color: var(--primary); }
.slot.selected { background: var(--primary); border-color: var(--primary); color: #fff; }

.summary-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-top: 16px;
  padding: 14px;
  background: #eef4ff;
  border-radius: 12px;
  flex-wrap: wrap;
}

/* Booking list */
.booking {
  display: flex;
  justify-content: space-between;
